pub(crate) fn envelope_response(
    status: StatusCode,
    code: i32,
    message: &str,
    description: &str,
) -> Response {
    envelope_json(status, code, None, message, description)
}

pub(crate) fn envelope_json(
    status: StatusCode,
    code: i32,
    data: Option<Value>,
    message: &str,
    description: &str,
) -> Response {
    (
        status,
        Json(Envelope {
            code,
            data,
            message: message.to_owned(),
            description: description.to_owned(),
        }),
    )
        .into_response()
}
